def table_health(df):
    return {
        "rows": df.count(),
        "null_ids": df.filter(F.col("respondent_id").isNull()).count(),
        "null_weights": df.filter(F.col("final_weight").isNull()).count(),
        "min_weight": df.agg({"final_weight": "min"}).collect()[0][0],
        "max_weight": df.agg({"final_weight": "max"}).collect()[0][0],
    }
